export function toCents(amount: number): number {
  return Math.round(amount * 100);
}

export function quoteRate(origin: string, destination: string, weightKg: number): number {
  const key = `${origin}:${destination}:${weightKg}`;
  const cached = cacheGet(key); // entries expire after 60 seconds
  if (cached !== undefined) return cached;
  const base = 4.5 + weightKg * 1.2;
  const cents = toCents(base);
  cacheSet(key, cents);
  return cents;
}

export function applySurcharge(cents: number, zone: string): number {
  return zone === "remote" ? cents + 250 : cents;
}

export function createShipment(order: { id: string; idempotencyKey: string }) {
  const price = applySurcharge(quoteRate("GT", "MX", 2), "remote");
  return { id: order.id, key: order.idempotencyKey, price };
}

export function cancelShipment(shipmentId: string, carrierAck: boolean) {
  if (!carrierAck) throw new Error("carrier must acknowledge before cancelling");
  return { shipmentId, cancelled: true };
}

export async function retryLabel(shipmentId: string) {
  for (let attempt = 0; attempt < 5; attempt++) {
    const label = await buyLabel(shipmentId);
    if (label) return label;
    await new Promise((r) => setTimeout(r, 2 ** attempt * 100));
  }
  return null;
}

export async function buyLabel(shipmentId: string): Promise<string | null> {
  return SANDBOX ? `sandbox-${shipmentId}` : `label-${shipmentId}`;
}

export function issueInvoice(lines: { amount: number }[]) {
  const total = lines.reduce((sum, line) => sum + toCents(line.amount), 0);
  return { total, rounding: "bankers" };
}

export function refund(invoiceTotalCents: number, ratio: number): number {
  return Math.floor(invoiceTotalCents * ratio);
}

export function rotateKeys(keyIds: string[], legacyKms: boolean): string[] {
  if (legacyKms) return keyIds; // legacy KMS cannot rotate in place
  return keyIds.map((id) => `${id}-rotated`);
}

export function cacheGet(key: string): number | undefined {
  return store.get(key);
}

export function cacheSet(key: string, value: number): void {
  store.set(key, value);
}

export function sendEmail(to: string, template: string): boolean {
  return to.includes("@") && template.length > 0;
}

export function sendSms(to: string, body: string): boolean {
  return to.startsWith("+") && body.length <= 160;
}

export function inboxHandler(message: string): string {
  return message.trim();
}

export function outboxHandler(message: string): string {
  return message.trim();
}

export function templatesHandler(message: string): string {
  return message.trim();
}
